    var recAttrs = ' data-key="' + escapeHtml(d.key || "") + '" data-name="' + escapeHtml(dispName) + '" data-sci="' + escapeHtml(sci) +
      '" data-lat="' + (d.lat == null ? "" : d.lat) + '" data-lon="' + (d.lon == null ? "" : d.lon) +
      '" data-date="' + escapeHtml(d.date || "") + '" data-url="' + escapeHtml(d.url || "") + '"';
