        function lgStart(x, y) { if (!legendIdle()) return; lgFired = false; clearTimeout(lgT); lgX = x; lgY = y; lgT = setTimeout(function () { lgFired = true; holdFeedback(d); fitFetched(); }, holdDelay()); }
