        d.addEventListener("touchmove", function (e) { var tt = e.touches && e.touches[0]; if (tt && (Math.abs(tt.clientX - lgX) > 12 || Math.abs(tt.clientY - lgY) > 12)) clearTimeout(lgT); }, { passive: true });
