          var app = location.origin + location.pathname + "?drive=" + encodeURIComponent(u);
          closeAnchoredMenu();
          var copied = function () { setStatus(t("drive.linkCopied")); };
          if (navigator.share) navigator.share({ title: "BirdsWhere", url: app }).catch(function () {});
