          var mxt = 0, curt = cell[week] ? cell[week][s] : 0;
          for (wk = 1; wk <= 48; wk++) { v = cell[wk] ? cell[wk][s] : 0; if (v > mxt) mxt = v; }
          agg[s] = mxt > 0 ? Math.min(100, (curt / mxt) * 100) : NaN;
